#!/usr/bin/env bash
# ccx server bootstrap — installs the CloudConnexa connector and enrols this host
# using a one-time connector profile token generated by `ccx add` / `ccx token`.
# Mirrors the CloudConnexa portal's own install steps (portal script v1.0.6), adding --token.
# Usage: sudo bash install.sh <TOKEN> [--force]
set -euo pipefail

CLOUDCONNEXA_BASEURL_DEFAULT='https://network-gateway.openvpn.com/network-gate/api/v1/profiles/'
REPO_KEY_URL='https://packages.openvpn.net/packages-repo.gpg'

die() { echo "ccx install: $*" >&2; exit 1; }

TOKEN="${1:-}"
FORCE=""
[ "${2:-}" = "--force" ] && FORCE="--force"
[ -n "$TOKEN" ] || die "missing token. Usage: sudo bash install.sh <TOKEN> [--force]"
[ "$(id -u)" -eq 0 ] || die "must run as root (use sudo)"
[ -r /etc/os-release ] || die "cannot detect distribution (/etc/os-release missing)"

# shellcheck disable=SC1091
. /etc/os-release
DISTRO_ID="${ID:-unknown}"
DISTRO_LIKE="${ID_LIKE:-}"

install_debian_family() {
  apt-get update
  apt-get install -y curl lsb-release
  mkdir -p /etc/apt/keyrings
  curl -fsSL "$REPO_KEY_URL" -o /etc/apt/keyrings/openvpn.asc
  echo "deb [signed-by=/etc/apt/keyrings/openvpn.asc] https://packages.openvpn.net/openvpn3/debian $(lsb_release -c -s) main" \
    > /etc/apt/sources.list.d/openvpn-packages.list
  apt-get update
  apt-get install -y python3-openvpn-connector-setup
}

install_rhel_family() {
  # TODO(VERIFY): copy the repo setup from the portal's RHEL/Alma/Rocky/Fedora scripts
  # (https://network-gateway.openvpn.com/network-gate/api/v1/scripts/<slug>/host/<slug>.sh).
  die "RHEL-family support not implemented yet (distro: $DISTRO_ID)"
}

case "$DISTRO_ID" in
  ubuntu|debian|raspbian) install_debian_family ;;
  rhel|almalinux|rocky|centos|fedora) install_rhel_family ;;
  *)
    case "$DISTRO_LIKE" in
      *debian*) install_debian_family ;;
      *rhel*|*fedora*) install_rhel_family ;;
      *) die "unsupported distribution: $DISTRO_ID" ;;
    esac
    ;;
esac

echo "Enrolling this host with CloudConnexa..."
# shellcheck disable=SC2086
CLOUDCONNEXA_BASEURL="${CLOUDCONNEXA_BASEURL:-$CLOUDCONNEXA_BASEURL_DEFAULT}" \
  openvpn-connector-setup --token "$TOKEN" $FORCE \
  || die "openvpn-connector-setup failed. If this host was enrolled before, re-run with --force; if the token was used or replaced, run 'ccx token <name>' on your laptop."

echo "Done. Check from your laptop: ccx status <name> --wait 2m"
